/*
 * A009303  If a, b in sequence, so is ab+4.
 * https://oeis.org/A009303
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 9, u16 n <= 48, u32 n <= 48, u64 n <= 48, u128 n <= 48,
 *            big any n
 * Helpers:   mul_plus_four
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * OEIS A009303: a(1) = 2, a(n) = smallest number > a(n-1) such that
 * it can be written as x·y + 4 with x,y in {a(k)}.
 * The sequence is generated by maintaining a min‑heap of all candidates
 * a(i)·a(j)+4 and emitting them in increasing order.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>
#include <limits.h>
#include <stdlib.h>
#include "../utils/mul_plus_four.h"

/* internal node used in the candidate heap */
struct Node {
    idx_t  i;          /* index of first factor      */
    idx_t  j;          /* index of second factor     */
    seq_t  val;        /* value a(i) * a(j) + 4      */
};

/* static cache of produced sequence values */
static seq_t *cache      = NULL;
static size_t cache_len  = 0;      /* number of stored values     */
static size_t cache_cap  = 0;      /* allocated capacity          */

/* static min‑heap of candidate nodes */
static struct Node *heap      = NULL;
static size_t heap_size  = 0;      /* number of elements in heap  */
static size_t heap_cap    = 0;      /* allocated size              */

/* last value emitted; used to suppress duplicates */
static seq_t last_val       = 0;
static bool  last_val_set   = false;

/* ------------------------------------------------------------------ */
/* helper for growing the cache array */
static void grow_cache(void)
{
    if (cache_len == cache_cap) {
        size_t new_cap = cache_cap ? cache_cap * 2 : 2;
        seq_t *tmp = (seq_t*)realloc(cache, new_cap * sizeof(seq_t));
        if (!tmp) abort();               /* out of memory */
        cache = tmp;
        cache_cap = new_cap;
    }
}

/* helper for growing the heap array */
static void grow_heap(void)
{
    if (heap_size == heap_cap) {
        size_t new_cap = heap_cap ? heap_cap * 2 : 2;
        struct Node *tmp = (struct Node*)realloc(heap, new_cap * sizeof(struct Node));
        if (!tmp) abort();               /* out of memory */
        heap = tmp;
        heap_cap = new_cap;
    }
}

/* push a candidate (i,j) onto the min‑heap */
static void heap_push(idx_t i, idx_t j)
{
    seq_t val;
    if (mul_plus_four(cache[i], cache[j], &val))
        return;                   /* overflow – discard this candidate */

    grow_heap();

    size_t k = heap_size++;
    heap[k].i = i;
    heap[k].j = j;
    heap[k].val = val;

    /* sift up */
    while (k > 0) {
        size_t p = (k - 1) >> 1;
        if (heap[p].val <= heap[k].val)
            break;
        struct Node tmp = heap[p];
        heap[p] = heap[k];
        heap[k] = tmp;
        k = p;
    }
}

/* pop the smallest node from the heap */
static struct Node heap_pop(void)
{
    struct Node res = heap[0];
    heap[0] = heap[--heap_size];

    size_t k = 0;
    while (1) {
        size_t left = k * 2 + 1;
        if (left >= heap_size)
            break;
        size_t right = left + 1;
        size_t smallest = (right < heap_size && heap[right].val < heap[left].val)
                          ? right : left;
        if (heap[k].val <= heap[smallest].val)
            break;
        struct Node tmp = heap[k];
        heap[k] = heap[smallest];
        heap[smallest] = tmp;
        k = smallest;
    }
    return res;
}

/* ------------------------------------------------------------------ */
/* initialise cache and heap with the first term 2 */
static void init_sequence(void)
{
    cache_cap = 1;
    cache = (seq_t*)malloc(cache_cap * sizeof(seq_t));
    if (!cache) abort();                 /* out of memory */
    cache[0] = (seq_t)2;
    cache_len = 1;
    last_val = cache[0];
    last_val_set = true;

    heap_cap = 4;
    heap = (struct Node*)malloc(heap_cap * sizeof(struct Node));
    if (!heap) abort();                  /* out of memory */
    heap_size = 0;
    heap_push(0, 0);                     /* first candidate 2*2+4 = 8 */
}

/* generate terms until cache_len >= n */
static void generate_terms_up_to(idx_t n)
{
    while (cache_len < n) {
        if (heap_size == 0)
            break;                   /* no more candidates – should not happen */

        struct Node node = heap_pop();

        bool is_new = false;
        if (!last_val_set || node.val != last_val) {
            grow_cache();
            cache[cache_len++] = node.val;
            last_val = node.val;
            last_val_set = true;
            is_new = true;
        }

        /* push next candidate for the same pair (i, j+1) */
        if (node.j + 1 < cache_len)
            heap_push(node.i, node.j + 1);

        /* if we added a new term, push its own initial candidate */
        if (is_new)
            heap_push(cache_len - 1, cache_len - 1);
    }
}

/* ------------------------------------------------------------------ */
/* public function required by the build system */
seq_t a(idx_t n)
{
    if (cache_len == 0)
        init_sequence();

    if (n > cache_len)
        generate_terms_up_to(n);

    return cache[n - 1];
}
